    if inv and inv.investors then
        local factors=__slctx.HaloPlan.fixedFactors(v.halo,v.evolution,inv.investors,__slctx.CONFIG,inv.perInvestor)
        __slctx.HaloPlan.factorReadiness(v,factors)
